SET ANSI_NULLS
ON GO
SET QUOTED_IDENTIFIER
ON GO ALTER PROCEDURE [ dbo ].[ procTICS_ValidateDataTICS_DEV ] @ ZREQ_ID CHAR (15),
    @ ERROR_NO VARCHAR (MAX) = '''',
    @ IS_ERROR BIT OUTPUT,
    @ ErrorDesc VARCHAR (MAX) OUTPUT AS /* DECLARE @ZREQ_ID CHAR(15), @IS_ERROR BIT, @ErrorDesc VARCHAR(MAX) /*EXEC [dbo].[procTICS_ValidateDataTICS] @ZREQ_ID = @ZREQ_ID, @IS_ERROR = @IS_ERROR OUTPUT, @ErrorDesc = @ErrorDesc OUTPUT*/
SELECT @ IS_ERROR,
    @ ErrorDesc
SELECT @ ZREQ_ID = ''202401290000009'' * / Declare @ msg NVARCHAR (MAX) = ''''
SELECT @ IS_ERROR = 0,
    @ ErrorDesc = '''' IF GETDATE () < ''2024/04/01 17:00:00''
    AND GETDATE () > ''2024/04/01 03:00:00'' BEGIN
SET @ IS_ERROR = 1
SET @ ErrorDesc = @ ErrorDesc + ''Non-insurance transactions have not been opened#'' END --return
UPDATE [ dbo ].[ ZSDDT0002_TICS ]
SET ZTRX_DATE = GETDATE ()
WHERE ZREQ_ID = @ ZREQ_ID
    AND @ ZREQ_ID LIKE ''4%''
SELECT * INTO # tmp
FROM  (
    SELECT value AS NomerValidasi
    FROM STRING_SPLIT (@ ERROR_NO,
            '','')) a
WHERE ISNUMERIC (NomerValidasi) = 1
SELECT *,
    CASE WHEN ZSO_PO_TYPE IN (''ZA01'',
        ''ZA04'',
        ''ZB01'',
        ''ZB04'') THEN ZZNET_AMT - (ZPRM_AMT + ZDISC_AMT + ZSTAMP_AMT + ZPOL_COST_AMT) WHEN ZSO_PO_TYPE IN (''PA01'',
        ''PA02'',
        ''PA03'',
        ''PB01'',
        ''PB02'',
        ''PB03'',
        ''PC01'',
        ''PC02'',
        ''PD01'',
        ''PD02'',
        ''PD03'') THEN ZZNET_AMT - (ZRI_PRM_AMT + ZRI_COMM_AMT) WHEN ZSO_PO_TYPE IN (''ZA02'',
        ''PA16'',
        ''PA17'',
        ''ZB02'',
        ''PB06'',
        ''PB07'',
        ''PD06'',
        ''PD07'') THEN ZZNET_AMT - (ZPRM_AMT + ZRI_COMM_AMT) END AS Selisih,
    convert (char (2),
        '''') TRX_TYPE INTO # ZSDDT0002_TICS
FROM [ dbo ].[ ZSDDT0002_TICS ]
WHERE ZREQ_ID = @ ZREQ_ID
    AND NOT ZSO_PO_TYPE = ''PE01''
UPDATE a
SET a.TRX_TYPE = CASE WHEN b.doc_indc IN (''SOPO'',
        ''POSO'') THEN ''03'' WHEN b.doc_indc = ''SO'' THEN ''01'' WHEN b.doc_indc = ''PO'' THEN ''02'' END,
    a.ZMSG = '''',
    a.ztype = ''I''
FROM # ZSDDT0002_TICS a
INNER JOIN  (
    SELECT ZREQ_ID,
        RTRIM (STRING_AGG (doc_indc,
                '''')) doc_indc
    FROM  (
        SELECT DISTINCT ZREQ_ID,
            RTRIM (doc_indc) doc_indc
        FROM # ZSDDT0002_TICS a
        INNER JOIN dst_mMappingSOPOType b
        ON a.ZSO_PO_TYPE = b.so_po_type) a
    GROUP BY ZREQ_ID) b
ON a.ZREQ_ID = b.ZREQ_ID
WHERE a.zreq_id = @ ZREQ_ID IF NOT EXISTS (
    SELECT 1
    FROM ZSDDT0002_LOG_TICS
    WHERE ZREQ_ID_TICS = @ ZREQ_ID)
    AND NOT EXISTS (
    SELECT 1
    FROM # tmp
    WHERE NomerValidasi = 1) BEGIN
SET @ IS_ERROR = 1
SET @ msg = ''1.ZSDDT0002_LOG is not exists.#''
UPDATE a
SET ZMSG = ISNULL (RTRIM (ZMSG),
        '''') + @ msg
FROM # ZSDDT0002_TICS a
WHERE NOT ZZTRX_TYPE = TRX_TYPE
SET @ ErrorDesc = @ ErrorDesc + @ msg END IF EXISTS (
    SELECT 1
    FROM # ZSDDT0002_TICS
    WHERE NOT ZZTRX_TYPE = TRX_TYPE)
    AND NOT EXISTS (
    SELECT 1
    FROM # tmp
    WHERE NomerValidasi = 2) BEGIN
SET @ IS_ERROR = 1
SET @ msg = ''2.Invalid ZZTRX_TYPE.#''
UPDATE a
SET ZMSG = ISNULL (RTRIM (ZMSG),
        '''') + @ msg
FROM # ZSDDT0002_TICS a
WHERE NOT ZZTRX_TYPE = TRX_TYPE
SET @ ErrorDesc = @ ErrorDesc + @ msg END IF (EXISTS (
        SELECT 1
        FROM # ZSDDT0002_TICS
        WHERE ZDOC_TYPE IN (''01'',
                ''02''))
        AND EXISTS (
        SELECT 1
        FROM # ZSDDT0002_TICS
        WHERE ZDOC_TYPE NOT IN (''01'',
                ''02'')))
    OR  (EXISTS (
        SELECT 1
        FROM # ZSDDT0002_TICS
        WHERE ZDOC_TYPE IN (''03'',
                ''04''))
        AND EXISTS (
        SELECT 1
        FROM # ZSDDT0002_TICS
        WHERE ZDOC_TYPE NOT IN (''03'',
                ''04'')))
    AND NOT EXISTS (
    SELECT 1
    FROM # tmp
    WHERE NomerValidasi = 3) BEGIN
SET @ IS_ERROR = 1
SET @ msg = ''3.Policy and claim document types should not be merged.#''
UPDATE a
SET ZMSG = ISNULL (RTRIM (ZMSG),
        '''') + @ msg
FROM # ZSDDT0002_TICS a
WHERE a.ZDOC_TYPE IN (''01'',
        ''02'')
    AND NOT EXISTS (
    SELECT 1
    FROM # ZSDDT0002_TICS b
    WHERE b.ZDOC_TYPE NOT IN (''01'',
            ''02''))
UPDATE a
SET ZMSG = ISNULL (RTRIM (ZMSG),
        '''') + @ msg
FROM # ZSDDT0002_TICS a
WHERE a.ZDOC_TYPE IN (''03'',
        ''04'')
    AND NOT EXISTS (
    SELECT 1
    FROM # ZSDDT0002_TICS b
    WHERE b.ZDOC_TYPE NOT IN (''03'',
            ''04''))
SET @ ErrorDesc = @ ErrorDesc + @ msg END IF EXISTS (
    SELECT 1
    FROM # ZSDDT0002_TICS
    WHERE RTRIM (ISNULL (ZZLOA,
                '''')) = ''''
        OR RTRIM (ISNULL (ZMATERIAL,
                '''')) = ''''
        OR RTRIM (ISNULL (ZZPORTFOLIO,
                '''')) = ''''
        OR RTRIM (ISNULL (ZZPRODUCT,
                '''')) = '''')
    AND NOT EXISTS (
    SELECT 1
    FROM # tmp
    WHERE NomerValidasi = 4) BEGIN
SET @ IS_ERROR = 1
SET @ msg = ''4.LOA, MATERIAL, PORTFOLIO, and PRODUCT must be filled in.#''
UPDATE a
SET ZMSG = ISNULL (RTRIM (ZMSG),
        '''') + @ msg
FROM # ZSDDT0002_TICS a
WHERE RTRIM (ISNULL (ZZLOA,
            '''')) = ''''
    OR RTRIM (ISNULL (ZMATERIAL,
            '''')) = ''''
    OR RTRIM (ISNULL (ZZPORTFOLIO,
            '''')) = ''''
    OR RTRIM (ISNULL (ZZPRODUCT,
            '''')) = ''''
SET @ ErrorDesc = @ ErrorDesc + @ msg END IF (EXISTS (
        SELECT 1
        FROM # ZSDDT0002_TICS a
        WHERE EXISTS (
            SELECT 1
            FROM ZSDDT0002 b
            WHERE a.ZZDOC_NBR = b.ZZDOC_NBR
                AND a.ZDOC_TYPE = b.ZDOC_TYPE
                AND a.ZZSEQ_NBR_INS = b.ZZSEQ_NBR_INS
                AND a.ZRI_SEQ_NBR = b.ZRI_SEQ_NBR
                AND b.ZTYPE = ''S''))
        OR EXISTS (
        SELECT 1
        FROM # ZSDDT0002_TICS a
        WHERE EXISTS (
            SELECT 1
            FROM ZSDDT0002_SOPO b
            WHERE a.ZZDOC_NBR = b.ZZDOC_NBR
                AND a.ZDOC_TYPE = b.ZDOC_TYPE
                AND a.ZZSEQ_NBR_INS = b.ZZSEQ_NBR_INS
                AND a.ZRI_SEQ_NBR = b.ZRI_SEQ_NBR
                AND ISNULL (b.ZTYPE,
                    ''I'') = ''D'')))
    AND NOT EXISTS (
    SELECT 1
    FROM # tmp
    WHERE NomerValidasi = 5) BEGIN IF @ ZREQ_ID LIKE ''4%'' BEGIN
DELETE a
FROM ZSDDT0002_TICS a
WHERE EXISTS (
    SELECT 1
    FROM ZSDDT0002 b
    WHERE a.ZZDOC_NBR = b.ZZDOC_NBR
        AND a.ZDOC_TYPE = b.ZDOC_TYPE
        AND a.ZZSEQ_NBR_INS = b.ZZSEQ_NBR_INS
        AND a.ZRI_SEQ_NBR = b.ZRI_SEQ_NBR
        AND b.ZTYPE = ''S'')
    AND a.ZREQ_ID = @ ZREQ_ID
DELETE a
FROM # ZSDDT0002_TICS a
WHERE EXISTS (
    SELECT 1
    FROM ZSDDT0002 b
    WHERE a.ZZDOC_NBR = b.ZZDOC_NBR
        AND a.ZDOC_TYPE = b.ZDOC_TYPE
        AND a.ZZSEQ_NBR_INS = b.ZZSEQ_NBR_INS
        AND a.ZRI_SEQ_NBR = b.ZRI_SEQ_NBR
        AND b.ZTYPE = ''S'')
DELETE c
FROM ZSDDT0002_SOPO c
WHERE EXISTS (
    SELECT 1
    FROM ZSDDT0002_SOPO a
    WHERE EXISTS (
        SELECT 1
        FROM # ZSDDT0002_TICS b
        WHERE a.ZZDOC_NBR = b.ZZDOC_NBR
            AND a.ZDOC_TYPE = b.ZDOC_TYPE
            AND a.ZZSEQ_NBR_INS = b.ZZSEQ_NBR_INS
            AND a.ZRI_SEQ_NBR = b.ZRI_SEQ_NBR)
        AND ISNULL (a.ZTYPE,
            ''I'') = ''I''
        AND c.ZREQ_ID = a.ZREQ_ID
        AND c.MANDT = a.MANDT
        AND c.ZACTION = a.ZACTION)
UPDATE a
SET a.count_TICS = b.count_TICS
FROM ZSDDT0002_LOG_TICS a
INNER JOIN  (
    SELECT ZREQ_ID,
        COUNT (1) count_TICS
    FROM # ZSDDT0002_TICS
    GROUP BY ZREQ_ID) b
ON a.ZREQ_ID_TICS = b.ZREQ_ID
WHERE a.ZREQ_ID_TICS = @ ZREQ_ID END ELSE BEGIN
SET @ IS_ERROR = 1
SET @ msg = ''5.Document number/ document type already exists.#''
UPDATE a
SET ZMSG = ISNULL (RTRIM (ZMSG),
        '''') + @ msg
FROM # ZSDDT0002_TICS a
WHERE EXISTS (
    SELECT 1
    FROM ZSDDT0002 b
    WHERE a.ZZDOC_NBR = b.ZZDOC_NBR
        AND a.ZDOC_TYPE = b.ZDOC_TYPE
        AND a.ZZSEQ_NBR_INS = b.ZZSEQ_NBR_INS
        AND a.ZRI_SEQ_NBR = b.ZRI_SEQ_NBR
        AND b.ZTYPE = ''S'')
SET @ ErrorDesc = @ ErrorDesc + @ msg END END ELSE BEGIN
DELETE c
FROM ZSDDT0002_SOPO c
WHERE EXISTS (
    SELECT 1
    FROM ZSDDT0002_SOPO a
    WHERE EXISTS (
        SELECT 1
        FROM # ZSDDT0002_TICS b
        WHERE a.ZZDOC_NBR = b.ZZDOC_NBR
            AND a.ZDOC_TYPE = b.ZDOC_TYPE
            AND a.ZZSEQ_NBR_INS = b.ZZSEQ_NBR_INS
            AND a.ZRI_SEQ_NBR = b.ZRI_SEQ_NBR)
        AND ISNULL (a.ZTYPE,
            ''I'') = ''I''
        AND c.ZREQ_ID = a.ZREQ_ID
        AND c.MANDT = a.MANDT
        AND c.ZACTION = a.ZACTION) END ---------------========POLIS==========------------- IF EXISTS (
    SELECT 1
    FROM  (
        SELECT ZZPOL_NBR
        FROM  (
            SELECT DISTINCT ZZPOL_NBR
            FROM # ZSDDT0002_TICS
            WHERE ZDOC_TYPE IN (''01'',
                    ''02'')) a
        GROUP BY ZZPOL_NBR
        HAVING COUNT (1) > 1) a)
    AND NOT EXISTS (
    SELECT 1
    FROM # tmp
    WHERE NomerValidasi = 6) BEGIN
SET @ IS_ERROR = 1
SET @ msg = ''6.In the policy data submission, only one policy is allowed to be sent in one ZREQ ID.#''
UPDATE a
SET ZMSG = ISNULL (RTRIM (ZMSG),
        '''') + @ msg
FROM # ZSDDT0002_TICS a
WHERE EXISTS (
    SELECT 1
    FROM  (
        SELECT DISTINCT ZZPOL_NBR
        FROM # ZSDDT0002_TICS
        WHERE ZDOC_TYPE IN (''01'',
                ''02'')) a
