INSERT INTO "Tasks" ("Id", "AssignedToUserId", "CategoryId", "CreatedAt", "Description", "DueDate", "Priority", "ProjectId", "StartDate", "Status", "Tags", "Title", "UpdatedAt", "Obstacle", "Solution", "Progress", "ParentTaskId", "Milestone", "CompanyId") VALUES (616, 'f01ce23c-f681-4871-aee4-51eac2e0cc7e', 9, '2026-09-10 07:49:54.2793016', 'Membangun engine utilitas local storage untuk penyimpanan file terstruktur di root /storage/, menaikkan batas body parser ke 10MB di seluruh service, serta mengonfigurasi ServeStaticModule dan proxy Vite untuk file preview langsung.', '2026-08-28 00:00:00', 1, 9, '2026-08-26 00:00:00', 2, '["Sheet:Glenn"]', 'Implementasi Engine Penyimpanan File Fisik Lokal, Penyesuaian Batas Payload, dan Proxy Preview Berkas di TICS v2.', '2026-09-10 07:49:54.2793017', 'Service backend belum memiliki mekanisme penyimpanan fisik untuk berkas tanda tangan, paraf, dan lampiran uploader sehingga memicu error HTTP 413 Request Entity Too Large dan ketiadaan fitur preview dokumen.', 'Membangun engine utilitas local storage untuk penyimpanan file terstruktur di root /storage/, menaikkan batas body parser ke 10MB di seluruh service, serta mengonfigurasi ServeStaticModule dan proxy Vite untuk file preview langsung.', 100, NULL, 'Master Data', 1);
INSERT INTO "Tasks" ("Id", "AssignedToUserId", "CategoryId", "CreatedAt", "Description", "DueDate", "Priority", "ProjectId", "StartDate", "Status", "Tags", "Title", "UpdatedAt", "Obstacle", "Solution", "Progress", "ParentTaskId", "Milestone", "CompanyId") VALUES (617, 'f01ce23c-f681-4871-aee4-51eac2e0cc7e', 9, '2026-09-10 07:49:54.281745', 'Implementasikan encrypted queue job yang idempotent, migration dan status provisioning, app-only token, locking nomor DOTS, retry terstruktur, logging aman, serta monitoring real-time worker dan SharePoint.', '2026-08-31 00:00:00', 2, 7, '2026-08-31 00:00:00', 2, '["Sheet:Glenn"]', 'Refactor dan Optimasi Create Transaction DOTS dengan Asynchronous SharePoint Queue.', '2026-09-10 07:49:54.281745', 'Submit transaksi menghasilkan HTTP 500 setelah database commit karena job kosong, schema queue belum lengkap, metadata tanggal tidak valid, serta retry berhenti sebelum provisioning SharePoint selesai.', 'Implementasikan encrypted queue job yang idempotent, migration dan status provisioning, app-only token, locking nomor DOTS, retry terstruktur, logging aman, serta monitoring real-time worker dan SharePoint.', 100, NULL, 'DOTS Request', 1);
