INSERT INTO "Tasks" ("Id", "AssignedToUserId", "CategoryId", "CreatedAt", "Description", "DueDate", "Priority", "ProjectId", "StartDate", "Status", "Tags", "Title", "UpdatedAt", "Obstacle", "Solution", "Progress", "ParentTaskId", "Milestone", "CompanyId") VALUES (619, 'f01ce23c-f681-4871-aee4-51eac2e0cc7e', 9, '2026-09-10 07:49:54.2867392', 'Menerapkan arsitektur dual-mode yang fleksibel (Worker 11 ms vs Batch Sinkron via .env), token caching 50 menit, serta standarisasi kepatuhan kualitas kode.', '2026-09-02 00:00:00', 1, 7, '2026-09-02 00:00:00', 2, '["Sheet:Glenn"]', 'Dual-Mode SharePoint Provisioning & Code Quality Hardening (api-dots)', '2026-09-10 07:49:54.2867393', 'Submit transaksi DOTS lambat (15–20 detik) akibat pemanggilan HTTP perizinan berulang ke Microsoft Graph tanpa mekanisme caching token OAuth.', 'Menerapkan arsitektur dual-mode yang fleksibel (Worker 11 ms vs Batch Sinkron via .env), token caching 50 menit, serta standarisasi kepatuhan kualitas kode.', 100, NULL, 'DOTS Request', 1);
INSERT INTO "Tasks" ("Id", "AssignedToUserId", "CategoryId", "CreatedAt", "Description", "DueDate", "Priority", "ProjectId", "StartDate", "Status", "Tags", "Title", "UpdatedAt", "Obstacle", "Solution", "Progress", "ParentTaskId", "Milestone", "CompanyId") VALUES (620, 'f01ce23c-f681-4871-aee4-51eac2e0cc7e', 9, '2026-09-10 07:49:54.2894155', 'Mengurangi god object dengan memisahkan komponen-komponen dan logic reusable menjadi file yang lebih kecil, serta membuat file cara setup background job yang diperlukan pada api-dots production', '2026-09-03 00:00:00', 1, 7, '2026-09-03 00:00:00', 2, '["Sheet:Glenn"]', 'Refactor lanjutan terkait pengurangan god object dan setup aturan job worker pada api-dots', '2026-09-10 07:49:54.2894155', 'Banyak sekali god object (satu file sangat panjang yang berisi logic dan komponen terpusat) pada project api-dots sehingga menyulitkan fase maintenance dan tracing code. Serta pada api-dots production berlum diimplementasikan background job worker untuk dapat menampung logic optimasi request create dots transaction', 'Mengurangi god object dengan memisahkan komponen-komponen dan logic reusable menjadi file yang lebih kecil, serta membuat file cara setup background job yang diperlukan pada api-dots production', 100, NULL, 'DOTS Request', 1);
INSERT INTO "Tasks" ("Id", "AssignedToUserId", "CategoryId", "CreatedAt", "Description", "DueDate", "Priority", "ProjectId", "StartDate", "Status", "Tags", "Title", "UpdatedAt", "Obstacle", "Solution", "Progress", "ParentTaskId", "Milestone", "CompanyId") VALUES (621, 'f01ce23c-f681-4871-aee4-51eac2e0cc7e', 9, '2026-09-10 07:49:54.2920795', 'Melakukan meeting bersama tim cash and bank membahas validasi dan feedback yang diperlukan terkait fitur yang diperlukan', '2026-09-04 00:00:00', 2, 7, '2026-09-04 00:00:00', 2, '["Sheet:Glenn"]', 'Meeting bersama user DOTS dan develop penyesuain dots terutama yang berhubungan cash and bank', '2026-09-10 07:49:54.2920796', 'Perlunya validasi dan feedback dari user DOTS terutama team cash and bank mengenai penyesuaian modul manajemen request dan transaction yang perlu dilakukan', 'Melakukan meeting bersama tim cash and bank membahas validasi dan feedback yang diperlukan terkait fitur yang diperlukan', 100, NULL, 'DOTS Request', 1);
INSERT INTO "Tasks" ("Id", "AssignedToUserId", "CategoryId", "CreatedAt", "Description", "DueDate", "Priority", "ProjectId", "StartDate", "Status", "Tags", "Title", "UpdatedAt", "Obstacle", "Solution", "Progress", "ParentTaskId", "Milestone", "CompanyId") VALUES (622, 'f01ce23c-f681-4871-aee4-51eac2e0cc7e', 9, '2026-09-10 07:49:54.2947102', 'Mengaktifkan penguncian seluruh baris seketika saat kursor masuk input (onFocus), mempercepat sinkronisasi heartbeat ke 2,5 detik, serta menerapkan jeda cooldown 300ms dengan indikator gembok berdenyut saat baris ditinggalkan.', '2026-09-07 00:00:00', 2, 7, '2026-09-04 00:00:00', 2, '["Sheet:Glenn"]', 'Implementasi Focus-Based Collaborative Row Lock dan Release Cooldown pada Modul Cash & Bank serta meeting progress bersama tim ERP TUGU', '2026-09-10 07:49:54.2947102', 'Penguncian baris sebelumnya hanya aktif saat user mengetik dan hanya di input itu saja (bukan 1 rows) sehingga rawan terjadi tabrakan input ketika kursor sudah berada di dalam sel, serta ketiadaan jeda transisi saat user berpindah baris.', 'Mengaktifkan penguncian seluruh baris seketika saat kursor masuk input (onFocus), mempercepat sinkronisasi heartbeat ke 2,5 detik, serta menerapkan jeda cooldown 300ms dengan indikator gembok berdenyut saat baris ditinggalkan.', 100, NULL, 'DOTS Request', 1);
INSERT INTO "Tasks" ("Id", "AssignedToUserId", "CategoryId", "CreatedAt", "Description", "DueDate", "Priority", "ProjectId", "StartDate", "Status", "Tags", "Title", "UpdatedAt", "Obstacle", "Solution", "Progress", "ParentTaskId", "Milestone", "CompanyId") VALUES (623, 'f01ce23c-f681-4871-aee4-51eac2e0cc7e', 9, '2026-09-10 07:49:54.2971782', 'Dibuat custom hook useGridRangeSelection untuk fitur drag-to-select dan batch copy format SAP (Ctrl+C), tombol salin 1-klik pada header kolom rujukan, serta pemisahan logika fase transaksi ke pure function isColumnApplicable yang selaras dengan aturan backend.', '2026-09-09 00:00:00', 2, 7, '2026-09-04 00:00:00', 2, '["Sheet:Glenn"]', 'Implementasi Range Selection & Multi-Row Copy ke SAP serta Refaktorisasi Cell Applicability pada Cash & Bank Grid', '2026-09-10 07:49:54.2971782', 'Tim Cash & Bank masih bergantung pada spreadsheet manual karena tabel DOTS belum mendukung blok multi-baris untuk disalin massal ke SAP, serta logika penonaktifan sel sebelumnya masih rapuh dan tercampur di komponen UI.', 'Dibuat custom hook useGridRangeSelection untuk fitur drag-to-select dan batch copy format SAP (Ctrl+C), tombol salin 1-klik pada header kolom rujukan, serta pemisahan logika fase transaksi ke pure function isColumnApplicable yang selaras dengan aturan backend.', 100, NULL, 'DOTS Request', 1);
