INSERT INTO "Tasks" ("Id", "AssignedToUserId", "CategoryId", "CreatedAt", "Description", "DueDate", "Priority", "ProjectId", "StartDate", "Status", "Tags", "Title", "UpdatedAt", "Obstacle", "Solution", "Progress", "ParentTaskId", "Milestone", "CompanyId") VALUES (709, '5d685a8f-5af6-4ce7-a18a-79cf658e64b8', 1, '2026-09-17 12:59:52.3203669', NULL, '2026-09-17 00:00:00', 1, 11, '2026-09-17 00:00:00', 2, NULL, 'Fixing PostgreSQL integration and Laravel controllers, refining the Next.js Queue and Reports & Analytics UI, and solidifying the overall ITSM workflow logic.', '2026-09-17 13:00:01.3638845', 'error 404 dan 500 pada API akibat kesalahan rute serta nama controller di backend Laravel, angka metrik dasbor Reports & Analytics yang menampilkan nilai 0 karena ketidaksesuaian struktur JSON dan query tanggal, antarmuka modul Queue serta Reports yang belum sesuai dengan standar desain Clean Modern Enterprise, kendala pemetaan peran dalam penyaringan Assignee tiket, serta masalah integrasi koneksi multi-database dengan PostgreSQL', 'mendaftarkan ulang rute API dan memperbaiki penamaan controller, menyesuaikan struktur respons JSON serta menambahkan rentang jam pada klausa query tanggal di Laravel, memperbarui tampilan frontend menggunakan Material UI berorientasi warna soft blue dan tipografi Inter, memfilter dropdown Assignee khusus untuk pengguna berperan technician, serta mengaktifkan ekstensi PHP yang dibutuhkan dan mengonfigurasi charset PostgreSQL', 100, NULL, 'Implementation', 1);
