INSERT INTO "Tasks" ("Id", "AssignedToUserId", "CategoryId", "CreatedAt", "Description", "DueDate", "Priority", "ProjectId", "StartDate", "Status", "Tags", "Title", "UpdatedAt", "Obstacle", "Solution", "Progress", "ParentTaskId", "Milestone", "CompanyId") VALUES (816, 'f01ce23c-f681-4871-aee4-51eac2e0cc7e', 11, '2026-10-07 01:59:44.6372243', NULL, '2026-10-01 00:00:00', 2, 31, '2026-10-01 00:00:00', 2, '["Sheet:Glenn"]', 'Perbaikan error saat ingin melakukan print dokumen output', '2026-10-07 01:59:44.6372246', 'Terdapat error Cannot access offset of type string on string dan Undefined array key "MAINT DATE FROM" pada saat ingin melakukan print output dokumen pada tics corp policy, hal ini disebabkan tidak ada nya null safety pada variabel-variabel yang digunakan untuk print documentnya', 'Fix error Cannot access offset of type string on string dan Undefined array key "MAINT DATE FROM" saat ingin print document dengan menambahkan handle null safety agar jika data satu variabel undefined maka dibuat null terlebih dahulu baru dilakukan processing lainnya', 100, NULL, 'Policy Automation', 1);
INSERT INTO "Tasks" ("Id", "AssignedToUserId", "CategoryId", "CreatedAt", "Description", "DueDate", "Priority", "ProjectId", "StartDate", "Status", "Tags", "Title", "UpdatedAt", "Obstacle", "Solution", "Progress", "ParentTaskId", "Milestone", "CompanyId") VALUES (817, 'f01ce23c-f681-4871-aee4-51eac2e0cc7e', 11, '2026-10-07 01:59:44.6419848', NULL, '2026-10-02 00:00:00', 2, 31, '2026-10-02 00:00:00', 2, '["Sheet:Glenn"]', 'Refaktorisasi OOP Modul Document Output dan Standarisasi Handler COB Fire', '2026-10-07 01:59:44.641985', 'Controller DocumentOutputController monolitik (~5.500 baris) memicu merge conflict parah saat dikerjakan multi-developer dan memiliki cacat indentasi visual pada klausul bilingual COB Fire.', 'Mengimplementasikan pola OOP (Template Method & Strategy Pattern) untuk mengisolasi logika per COB, memperbaiki format tabel klausul Fire, serta mengunci kalkulasi eksisting dengan test audit paritas sebagai standar bagi developer lain.', 100, NULL, 'Policy Automation', 1);
