INSERT INTO "Tasks" ("Id", "AssignedToUserId", "CategoryId", "CreatedAt", "Description", "DueDate", "Priority", "ProjectId", "StartDate", "Status", "Tags", "Title", "UpdatedAt", "Obstacle", "Solution", "Progress", "ParentTaskId", "Milestone", "CompanyId") VALUES (901, 'f01ce23c-f681-4871-aee4-51eac2e0cc7e', 12, '2026-10-15 13:29:10.9453859', 'Fix Provisioning SharePoint & Sinkronisasi Path Folder Transaksi Budget', '2026-10-14 00:00:00', 1, 7, '2026-10-14 00:00:00', 2, NULL, 'Fix Provisioning SharePoint & Sinkronisasi Path Folder Transaksi Budget', '2026-10-15 13:29:10.9527115', 'Transaksi ber-routing budget yang belum memiliki folder gagal di-retry secara permanen karena sistem memaksa lookup BP karyawan yang bernilai null ke TKYC, serta pembuatan folder berisiko menggunakan path yang salah dan tidak sinkron dengan frontend.', 'Menggunakan ApprovalRouting::sharePointCostCenter agar lokasi folder tetap konsisten, serta langsung memanfaatkan rantai persetujuan tersimpan di database (storedChain) untuk mengundang approver anggaran via /dots-approval tanpa lookup BP karyawan.', 100, NULL, 'Implementation', 1);
INSERT INTO "Tasks" ("Id", "AssignedToUserId", "CategoryId", "CreatedAt", "Description", "DueDate", "Priority", "ProjectId", "StartDate", "Status", "Tags", "Title", "UpdatedAt", "Obstacle", "Solution", "Progress", "ParentTaskId", "Milestone", "CompanyId") VALUES (902, 'f01ce23c-f681-4871-aee4-51eac2e0cc7e', 12, '2026-10-15 12:45:52.5360475', NULL, '2026-10-15 00:00:00', 1, 7, '2026-10-15 00:00:00', 2, '["FUNCTIONAL_BUG","Sheet:Glenn"]', 'Proteksi Scheduler Retry SharePoint & Penanganan Transaksi Historis', '2026-10-15 12:45:52.536049', 'Penambahan kolom status dengan default pending menyebabkan belasan ribu transaksi historis lama dan transaksi yang sudah ditolak/batal (3010/3020) ikut masuk ke dalam antrean retry scheduler, sehingga memicu pemborosan trafik Graph API dan risiko infinite retry loop.', 'Menjalankan migrasi idempoten untuk menandai transaksi lawas tanpa folder menjadi legacy, serta memperkuat query command scheduler dengan mengecualikan status gugur/batal (3010/3020) dan membatasi rentang usia transaksi yang diproses maksimal 30 hari ke belakang (--max-age-days=30).', 100, NULL, 'DOTS Request', 1);
