INSERT INTO "Tasks" ("Id", "AssignedToUserId", "CategoryId", "CreatedAt", "Description", "DueDate", "Priority", "ProjectId", "StartDate", "Status", "Tags", "Title", "UpdatedAt", "Obstacle", "Solution", "Progress", "ParentTaskId", "Milestone", "CompanyId") VALUES (910, '77474c1c-f8fc-4c0c-8028-0e37424b85bc', 1, '2026-10-17 09:24:11.1368874', 'Implementasi Open Telemetry di SC - Outbound', '2026-10-19 00:00:00', 2, 6, '2026-10-16 00:00:00', 2, NULL, 'Implementasi Open Telemetry di SC - Outbound', '2026-10-17 09:24:11.1385131', 'dibutuhkan open telemetry untuk dapat melakukan tracking data, request payload, alur proses data di dalam suatu aplikasi, untuk kebutuhan pengecekan data pengujian (testing) SIT', 'open telemetry sudah di implementasikan pada SC dan dapat di akses untuk melihat informasi data atau proses di dalam aplikasi SC secara langsung', 100, NULL, 'Implementation', 1);
INSERT INTO "Tasks" ("Id", "AssignedToUserId", "CategoryId", "CreatedAt", "Description", "DueDate", "Priority", "ProjectId", "StartDate", "Status", "Tags", "Title", "UpdatedAt", "Obstacle", "Solution", "Progress", "ParentTaskId", "Milestone", "CompanyId") VALUES (911, '66a785ea-7b91-4732-9566-e0eb676cbc60', 9, '2026-10-17 09:23:43.1902326', 'Melakukan sinkronisasi pada dokumen TSD agar sesuai dengan codebase yang diimplementasikan', '2026-10-16 00:00:00', 1, 4, '2026-10-16 00:00:00', 2, NULL, 'Melakukan sinkronisasi pada dokumen TSD agar sesuai dengan codebase yang diimplementasikan', '2026-10-17 09:23:43.1924213', 'Kunci privat RSA 2048-bit tertulis secara hardcoded di berkas config/integration.php sebagai fallback sehingga berisiko bocor melalui riwayat repositori Git.', 'Nilai hardcoded dihapus seutuhnya dan dialihkan murni ke environment variable, serta diterapkan prinsip fail-closed agar sistem menolak berjalan jika kunci belum dikonfigurasi.', 100, NULL, 'Implementation', 1);
