INSERT INTO "Tasks" ("Id", "AssignedToUserId", "CategoryId", "CreatedAt", "Description", "DueDate", "Priority", "ProjectId", "StartDate", "Status", "Tags", "Title", "UpdatedAt", "Obstacle", "Solution", "Progress", "ParentTaskId", "Milestone", "CompanyId") VALUES (924, 'f01ce23c-f681-4871-aee4-51eac2e0cc7e', 1, '2026-10-20 01:13:58.6958', 'Refactoring Polimorfisme Output Dokumen & Rincian Suku Premi Fire', '2026-10-16 00:00:00', 1, 31, '2026-10-16 00:00:00', 2, NULL, 'Refactoring Polimorfisme Output Dokumen & Rincian Suku Premi Fire', '2026-10-20 01:13:58.6995126', 'Dokumen service sebelumnya monolitik dan mencampurkan logika spesifik Fire ke base class, mengakibatkan suku premi pada polis multi-objek terakumulasi secara otomatis dan tidak bisa dirinci per objek dalam format tabel.', 'Memecah base class ke dalam 5 domain trait modular, memindahkan seluruh logika Fire ke FireDocumentService, serta menyajikan suku premi dalam tabel 2 kolom yang presisi (tarif tunggal jika seragam, atau dirinci per objek jika berbeda).', 100, NULL, 'Implementation', 1);
INSERT INTO "Tasks" ("Id", "AssignedToUserId", "CategoryId", "CreatedAt", "Description", "DueDate", "Priority", "ProjectId", "StartDate", "Status", "Tags", "Title", "UpdatedAt", "Obstacle", "Solution", "Progress", "ParentTaskId", "Milestone", "CompanyId") VALUES (925, 'f01ce23c-f681-4871-aee4-51eac2e0cc7e', 1, '2026-10-20 01:14:24.017366', 'Resolusi Konflik Merge UAT, Preservasi Fitur Marine, & Label Objek Fire', '2026-10-19 00:00:00', 1, 31, '2026-10-19 00:00:00', 2, NULL, 'Resolusi Konflik Merge UAT, Preservasi Fitur Marine, & Label Objek Fire', '2026-10-20 01:14:24.0197005', 'Merge dari branch uat menimbulkan konflik Git pada BaseDocumentService yang berisiko menghilangkan fitur running number klausul Marine Cargo, serta label baris suku premi Fire multi-objek belum memuat indeks pembeda antar objek.', 'Menyelesaikan konflik dengan mempertahankan base service tetap modular, mempreservasi logika Marine Cargo ke dalam trait terkait, memperbaiki penamaan label menjadi (Objek N), dan memastikan seluruh 40 skenario pengujian lulus 100%.', 100, NULL, 'Implementation', 1);
